#pragma once

#include <cstddef>
#include <cstdint>

namespace data::landmarks {

/**
 * Landmark lines around the sites in the git-ignored landmark_sites.txt, generated by
 * scripts/build_landmarks.py into src/data/landmarks_local.inc. Without that file the
 * tables are empty and no landmarks are drawn.
 */

/** Coordinates are in 1e-5 degree units. */
constexpr int32_t kUnitsPerDeg = 100000;

/** Drawing order follows the values: later kinds go on top. */
enum class Kind : uint8_t {
  River = 0,
  Island = 1,
  Shore = 2,
  Border = 3,
};

/**
 * Part of a polyline: its first point, then point_count - 1 deltas from kDeltas starting
 * at first_delta, each relative to the point before. The box covers every point.
 */
struct Chunk {
  int32_t lat0;
  int32_t lon0;
  int32_t min_lat;
  int32_t min_lon;
  int32_t max_lat;
  int32_t max_lon;
  uint32_t first_delta;
  uint16_t point_count;
  Kind kind;
};

struct Delta {
  int16_t dlat;
  int16_t dlon;
};

/** Sorted by kind. nullptr when there's no generated data. */
extern const Chunk* const kChunks;
extern const size_t kChunkCount;
extern const Delta* const kDeltas;

}  // namespace data::landmarks
